<style>.audit-summary{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:10px;margin-bottom:16px}.audit-summary div{border:1px solid #e5e7eb;border-radius:10px;padding:12px;background:linear-gradient(135deg,#fff,#f7f9fc)}.audit-summary span{display:block;color:#6b7280;font-size:.8rem}.audit-summary b{font-size:1.5rem}.audit-status{font-size:.72rem;padding:.28rem .5rem;border-radius:999px;font-weight:700}.audit-COCOK,.audit-COCOK---ROUTING-BERBEDA{background:#dcfce7;color:#166534}.audit-BERBEDA,.audit-SELISIH-NILAI,.audit-HANYA-LOKAL,.audit-HANYA-PROINT{background:#fee2e2;color:#991b1b}.audit-PERLU-PILIH-BON{background:#fef3c7;color:#92400e}.audit-CP-TIDAK-DITEMUKAN,.audit-ROUTING-TIDAK-COCOK{background:#e5e7eb;color:#374151}.status-badge{display:inline-block;font-size:.75rem;font-weight:600;padding:.25rem .6rem;border-radius:4px}.status-master-resep{background:#28a745;color:#fff}.status-shading{background:#ffc107;color:#1f2d3d}.status-top-paddry{background:#17a2b8;color:#fff}.status-top-cpb{background:#6c757d;color:#fff}.status-kestabilan{background:#7c3aed;color:#fff}.status-default{background:#e3f2fd;color:#1976d2}@media(max-width:900px){.audit-summary{grid-template-columns:repeat(2,1fr)}}</style>
<script src="/gg_app/plugins/AdminLTE-3.2.0/plugins/sweetalert2/sweetalert2.all.min.js"></script>
<script>
$(function(){let page=1,auditToken=0,pageRequest=null,auditRequest=null,summary={},auditResults=new Map();const esc=v=>$('<div>').text(v==null?'':String(v)).html();const numberDisplay=v=>{if(v==null||v==='')return '-';let s=String(v);if(s.startsWith('.'))return '0'+s;if(s.startsWith('-.'))return '-0'+s.slice(1);return s};const badge=s=>`<span class="audit-status audit-${esc(s).replaceAll(' ','-')}">${esc(s)}</span>`;const recipeStatusBadge=value=>{let label=value==null||value===''?'-':String(value),status=label.toLowerCase(),className='status-default';if(status==='master resep'||status==='master')className='status-master-resep';else if(status==='shading')className='status-shading';else if(status==='top paddry')className='status-top-paddry';else if(status==='top cpb')className='status-top-cpb';else if(status==='kestabilan'||status==='kesetabilan')className='status-kestabilan';return `<span class="status-badge ${className}">${esc(label)}</span>`};function params(){return{cp:$('#auditCp').val().trim(),source:$('#auditSource').val(),start:$('#auditStart').val(),end:$('#auditEnd').val()}}function error(xhr){let r=xhr.responseJSON||{};Swal.fire('Error',(r.message||'Gagal memuat audit.')+(r.request_id?' Request ID: '+r.request_id:''),'error')}
function loadRoutes(){$.getJSON('debug_detail_resep_api.php',{action:'routes'}).done(r=>{let html='<option value="">Pilih routing...</option>'+r.routes.map(x=>`<option value="${esc(x.code)}">${esc(x.code==='-'?'TANPA ROUTING':x.code+' - '+(x.name||'-'))} (${x.total})</option>`).join('');$('#auditRoute').html(html)}).fail(error)}
function showResult(x){let $tr=$(`tr[data-audit-id="${x.id}"]`);if(!$tr.length)return;$tr.find('.audit-source').text(x.source||'');$tr.find('.audit-bon').html(`${esc(x.bonno||'-')} ${x.candidate_count>1?`<small>(${x.candidate_count} pilihan)</small>`:''}`);$tr.find('.audit-result').html(`${badge(x.status)}<br><small class="text-muted">${esc(x.status_detail||'')}</small>`)}
function load(p=1,restart=false){page=p;if(pageRequest)pageRequest.abort();if(restart){auditToken++;if(auditRequest)auditRequest.abort();summary={};auditResults.clear();$('#sumMatch,#sumDiff,#sumAmbiguous,#sumMissing').text(0);$('#auditProgress').addClass('d-none')}let token=auditToken;$('#auditRows').html('<tr><td colspan="8" class="text-center">Memuat daftar resep lokal...</td></tr>');pageRequest=$.getJSON('debug_detail_resep_api.php',{...params(),page}).done(r=>{if(token!==auditToken)return;let html=r.rows.map(x=>{let q=x.recipe;return `<tr data-audit-id="${q.id}"><td><b>${esc(q.no_cp)}</b><br><small class="text-muted audit-source"></small></td><td>${esc(q.rtg_code||'-')} - ${esc(q.rtg_name||'-')}</td><td>${Number(q.is_manual)===1?'MANUAL':'PROINT'}</td><td>${recipeStatusBadge(q.status_resep_lipat)}</td><td>${esc(q.created_at)}</td><td class="audit-bon">-</td><td class="audit-result">${badge('MENUNGGU')}<br><small class="text-muted">Menunggu pemeriksaan ProInt</small></td><td><button class="btn btn-info btn-sm detail-audit" data-id="${q.id}"><i class="fas fa-balance-scale"></i> Bandingkan</button> <a class="btn btn-outline-secondary btn-sm" href="view_resep.php?resep_id=${q.id}"><i class="fas fa-eye"></i></a></td></tr>`}).join('');$('#auditRows').html(html||'<tr><td colspan="8" class="text-center">Tidak ada data.</td></tr>');r.rows.forEach(x=>{let result=auditResults.get(Number(x.recipe.id));if(result)showResult(result)});$('#sumTotal').text(r.total);let pages=Math.max(1,Math.ceil(r.total/r.limit)),nav=`<li class="page-item ${page===1?'disabled':''}"><button class="page-link audit-page" data-page="${page-1}" aria-label="Halaman sebelumnya">&laquo;</button></li>`;let shown=[1,pages,page-1,page,page+1].filter((v,i,a)=>v>=1&&v<=pages&&a.indexOf(v)===i).sort((a,b)=>a-b),previous=0;shown.forEach(i=>{if(previous&&i>previous+1)nav+='<li class="page-item disabled"><span class="page-link">...</span></li>';nav+=`<li class="page-item ${i===page?'active':''}"><button class="page-link audit-page" data-page="${i}">${i}</button></li>`;previous=i});nav+=`<li class="page-item ${page===pages?'disabled':''}"><button class="page-link audit-page" data-page="${page+1}" aria-label="Halaman berikutnya">&raquo;</button></li>`;$('#auditPager').html(nav);if(restart)loadAllIds(token)}).fail((xhr,status)=>{if(status!=='abort')error(xhr)}).always(()=>{pageRequest=null})}
function updateSummary(s){summary[s]=(summary[s]||0)+1;$('#sumMatch').text((summary.COCOK||0)+(summary['COCOK - ROUTING BERBEDA']||0));$('#sumDiff').text(summary.BERBEDA||0);$('#sumAmbiguous').text(summary['PERLU PILIH BON']||0);$('#sumMissing').text((summary['CP TIDAK DITEMUKAN']||0)+(summary['ROUTING TIDAK COCOK']||0))}
function loadAllIds(token){auditRequest=$.getJSON('debug_detail_resep_api.php',{action:'ids',...params()}).done(r=>{if(token!==auditToken)return;runBatches(r.ids||[],token)}).fail((xhr,status)=>{if(status!=='abort')error(xhr)}).always(()=>{auditRequest=null})}
function runBatches(ids,token){let done=0,total=ids.length;if(!total)return;$('#auditProgress').removeClass('d-none');$('#auditProgressText').text('Memeriksa seluruh data ProInt...');$('#auditProgressCount').text(`0/${total}`);$('#auditProgressBar').addClass('progress-bar-animated').css('width','0%');function next(){if(token!==auditToken)return;if(done>=total){$('#auditProgressText').text('Audit seluruh data ProInt selesai');$('#auditProgressBar').removeClass('progress-bar-animated');return}let batch=ids.slice(done,done+5);auditRequest=$.getJSON('debug_detail_resep_api.php',{action:'audit_batch',ids:batch.join(',')}).done(r=>{if(token!==auditToken)return;(r.rows||[]).forEach(x=>{auditResults.set(Number(x.id),x);showResult(x);updateSummary(x.status)});done+=batch.length;let pct=Math.round(done/total*100);$('#auditProgressText').text('Memeriksa seluruh data ProInt...');$('#auditProgressCount').text(`${done}/${total}`);$('#auditProgressBar').css('width',pct+'%');next()}).fail((xhr,status)=>{if(status!=='abort')error(xhr)}).always(()=>{auditRequest=null})}next()}
function detail(id,bon){$.getJSON('debug_detail_resep_api.php',{action:'detail',id,bonreq_id:bon||''}).done(r=>{let a=r.audit,chooser='',selected=a.selected_bon||{};if(a.candidates.length>1){chooser='<label>Pilih Bon ProInt:</label><div class="btn-group flex-wrap">'+a.candidates.map(b=>`<button class="btn btn-outline-primary btn-sm choose-bon" data-id="${id}" data-bon="${b.bonreqid}">${esc(b.bonno)} · ${esc(b.rtgname||'-')}</button>`).join('')+'</div>'}let bonInfo=selected.bonno?`<div class="mt-2"><strong>Bon No:</strong> ${esc(selected.bonno)} &nbsp; <strong>Routing ProInt:</strong> ${esc(selected.rtgname||'-')}</div>`:'';$('#auditBonChooser').html(`<div class="alert alert-light border"><b>${esc(a.recipe.no_cp)}</b> · ${badge(a.status)}<br><small>${esc(a.status_detail||'')}</small>${bonInfo}</div>`+chooser);$('#auditDetails').html(a.details.map(d=>{let l=d.local||{},p=d.proint||{},reason=(d.reasons||[]).join(', ')||d.status;return `<tr><td>${esc(d.kode)}</td><td>${esc(l.name||p.name||'-')}</td><td>${esc(numberDisplay(l.receipe))}</td><td>${esc(numberDisplay(p.qty))}</td><td>${esc(numberDisplay(l.cf))}</td><td>${esc(numberDisplay(p.cf))}</td><td>${esc(l.uom||'-')}</td><td>${esc(p.uom||'-')}</td><td>${badge(d.status)}<br><small class="text-muted">${esc(reason)}</small></td></tr>`}).join('')||'<tr><td colspan="9" class="text-center">Pilih Bon untuk membandingkan.</td></tr>');$('#auditDetailModal').modal('show')}).fail(error)}
$('#auditFilter').click(()=>load(1,true));$('#auditCp').keydown(e=>{if(e.key==='Enter')load(1,true)});$(document).on('click','.audit-page',function(){load(Number($(this).data('page')),false)}).on('click','.detail-audit',function(){detail($(this).data('id'))}).on('click','.choose-bon',function(){detail($(this).data('id'),$(this).data('bon'))});$('#auditExport').click(async()=>{let choice=await Swal.fire({title:'Pilih Jenis Export',text:'Ringkasan cepat memakai hasil audit yang sudah selesai.',icon:'question',showCancelButton:true,showDenyButton:true,confirmButtonText:'Ringkasan Cepat',denyButtonText:'Beserta Detail',cancelButtonText:'Batal'});if(choice.isDismissed)return;if(choice.isDenied){let q=new URLSearchParams(params());window.location='export_debug_detail_resep.php?'+q.toString();return}let expected=Number($('#sumTotal').text())||0;if(!expected||auditResults.size!==expected){Swal.fire('Audit Belum Selesai',`Tunggu sampai pemeriksaan selesai (${auditResults.size}/${expected}).`,'warning');return}Swal.fire({title:'Membuat ringkasan...',allowOutsideClick:false,didOpen:()=>Swal.showLoading()});fetch('export_debug_detail_resep.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows:Array.from(auditResults.values())})}).then(async response=>{if(!response.ok)throw new Error(await response.text()||'Export gagal.');let blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Audit_Ringkasan_Resep_'+Date.now()+'.xlsx';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);Swal.fire('Berhasil','Ringkasan audit diunduh.','success')}).catch(e=>Swal.fire('Export Gagal',e.message,'error'))});load(1,true)});
</script>
